/* Modern Glass Cockpit Canvas Override */
canvas {
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

/* Remove old PFD styling */
.pfd-container,
.pfd-main,
.pfd-center,
.pfd-info,
.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
