    flex-direction: column;
    gap: 0.4rem;
}

.button-row {
    display: flex;
    gap: 0.3rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
