    padding: 6px 16px;
    border-radius: 4px;
    font-family: 'Arial', sans-serif;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.5px;
    border: 1px solid #00aa66;
    box-shadow: 0 0 8px rgba(0, 255, 136, 0.3);
}

.armed-indicator {
    background: rgba(0, 0, 0, 0.85);
