    animation: pulse-armed 2s infinite;
}

.bottom-info-bar {
    position: absolute;
    bottom: 8px;
    left: 8px;
    right: 8px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
}

.system-status {
    display: flex;
    gap: 12px;
}

.status-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(0, 0, 0, 0.8);
    padding: 4px 8px;
    border-radius: 4px;
    border: 1px solid #333;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
}

.status-label {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    font-weight: 500;
    color: #87ceeb;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
}

.status-value {
    font-family: 'Courier New', monospace;
    font-size: 14px;
    font-weight: 600;
    color: #00ff88;
}

.position-info {
    background: rgba(0, 0, 0, 0.8);
    padding: 4px 10px;
    border-radius: 4px;
    border: 1px solid #333;
}

.coordinates {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    color: #ffcc00;
    letter-spacing: 0.5px;
}

/* Modern Glass Cockpit Canvas Override */
canvas {
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

/* Remove old PFD styling */
.pfd-container,
.pfd-main,
.pfd-center,
.pfd-info,
.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
.armed-status,
.flight-mode {
    display: none;
}

/* Animations for modern glass cockpit */
@keyframes pulse-armed {
    0%, 100% { 
        opacity: 1;
        transform: scale(1);
    }
    50% { 
        opacity: 0.8;
        transform: scale(1.02);
    }
}

/* Enhanced pulse animation for critical indicators */
@keyframes pulse {
    0%, 100% { 
        transform: scale(1);
        opacity: 1;
    }
    50% { 
        transform: scale(1.05);
        opacity: 0.8;
    }
}

/* G1000-Style Flight Data Panel */
.g1000-flight-data-panel {
    background: #0a0a0a;
    border: 2px solid #1e1e2e;
    border-radius: 8px;
    padding: 0.75rem;
}

.g1000-flight-data-panel h3 {
    color: #87ceeb;
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
    text-align: center;
    font-weight: 500;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    border-bottom: 1px solid #2d3748;
    padding-bottom: 0.5rem;
}

.g1000-data-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.data-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0.5rem;
}

.data-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: rgba(10, 10, 20, 0.8);
    padding: 0.4rem;
    border-radius: 4px;
    border: 1px solid #333;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
}

.data-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 500;
    color: #87ceeb;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.data-value {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    font-weight: 600;
    color: #00ff88;
    text-align: center;
}

/* Flight Controls Styles */
.control-groups {
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.control-group {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.button-row {
    display: flex;
    gap: 0.3rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
