    gap: 0.3rem;
    margin-bottom: 0.8rem;
}

.nav-buttons {
    display: flex;
    gap: 0.3rem;
}

/* Request Controls and Audio Styles */
.request-panel h3 {
    display: none;
}

.request-buttons {
    display: flex;
    gap: 0.3rem;
}

.audio-controls {
    display: flex;
