    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-color);
}

.main-header h1 {
    font-size: 2.2rem;
    font-weight: 600;
}

.header-controls {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.dump-link {
    background: var(--info-color);
    color: white;
    padding: 0.6rem 1.2rem;
    text-decoration: none;
    border-radius: 4px;
    font-size: 1.1rem;
    transition: background-color 0.3s;
}

.dump-link:hover {
    background: #138496;
}

.websocket-status {
    padding: 0.6rem 1.2rem;
