    border-radius: 0;
    box-shadow: none;
}

/* Status Overlays */
.pfd-overlays {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    z-index: 10;
}

.top-status-bar {
