    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-color);
}

.main-header h1 {
    font-size: 2.2rem;
    font-weight: 600;
}

.header-controls {
    display: flex;
