    gap: 1rem;
}

.dump-link {
    background: var(--info-color);
    color: white;
    padding: 0.6rem 1.2rem;
    text-decoration: none;
    border-radius: 4px;
    font-size: 1.1rem;
    transition: background-color 0.3s;
}

.dump-link:hover {
    background: #138496;
}

.websocket-status {
