}

.internet-status.offline {
    background: #f8d7da;
    color: #721c24;
}

.coord-inputs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.input-row {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.input-row label {
