    gap: 0.25rem;
}

.input-group label {
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--text-muted);
}

.input-group input {
    padding: 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 1.1rem;
}

.connection-buttons {
    display: flex;
    gap: 0.6rem;
}

/* Button Styles */
.btn {
    padding: 0.8rem 1.3rem;
    border: none;
    border-radius: 4px;
    font-size: 1.2rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--primary-color);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0056b3;
}

.btn-secondary {
    background: var(--secondary-color);
    color: white;
}

.btn-secondary:hover:not(:disabled) {
    background: #545b62;
}

.btn-success {
    background: var(--success-color);
    color: white;
}

.btn-success:hover:not(:disabled) {
    background: #1e7e34;
}

.btn-danger {
    background: var(--danger-color);
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #bd2130;
}

.btn-warning {
    background: var(--warning-color);
    color: var(--dark-color);
}

.btn-warning:hover:not(:disabled) {
    background: #e0a800;
}

.btn-info {
    background: var(--info-color);
    color: white;
}

.btn-info:hover:not(:disabled) {
    background: #138496;
}

.btn-connect {
    background: var(--success-color);
    color: white;
}

.btn-disconnect {
    background: var(--danger-color);
    color: white;
}

/* Modern Glass Cockpit Primary Flight Display */
.glass-pfd-panel {
    background: #0a0a0a;
    border: 2px solid #1e1e2e;
    border-radius: 12px;
    padding: 0.75rem;
}

.glass-pfd-panel h3 {
    color: #87ceeb;
    font-size: 1.2rem;
    margin-bottom: 0.75rem;
    text-align: center;
    font-weight: 500;
