        ctx.lineTo(-10, 0);
        ctx.moveTo(45, 0);
        ctx.lineTo(10, 0);
        ctx.stroke();

        // Wing tips (subtle downward angle)
        ctx.beginPath();
        ctx.moveTo(-45, 0);
        ctx.lineTo(-45, 4);
        ctx.moveTo(45, 0);
        ctx.lineTo(45, 4);
        ctx.stroke();

        // Center reference triangle (G1000 style)
        ctx.beginPath();
        ctx.moveTo(0, -8);
