        ALTITUDE_WIDTH: 90,
        VS_X: 625,
        VS_WIDTH: 15,
        HEADING_Y: 420,
        HEADING_HEIGHT: 50
    };

    // Modern glass cockpit color scheme
    const COLORS = {
        SKY_BLUE: '#4169E1',
        SKY_LIGHT: '#87CEEB',
        EARTH_BROWN: '#8B4513',
        EARTH_DARK: '#2F1B14',
        HORIZON_WHITE: '#FFFFFF',
